      letter-spacing: -0.04em;
    }

    .hero p {
      max-width: 65ch;
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .quiz-card {
      padding: 1.5rem;
      border-radius: 28px;
      border: 1px solid var(--border);
      background: var(--surface);
      box-shadow: var(--shadow);
      backdrop-filter: blur(10px);
    }

    .form-field {
      margin: 0;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-width: 0;
