359.       const helpId = `${question.id}-help`;
360.       const fieldsetDescribedBy = question.help ? ` aria-describedby="${helpId}"` : "";
361.       const helpMarkup = question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : "";
