388.           ${quizData.map(createQuestion).join("")}
389. 
390.           <div class="quiz-card">
391.             <div class="actions">
392.               <p class="hint">Choose one or more answers for each question, then check your score.</p>
393.               <button class="submit-btn" type="submit">Submit quiz</button>
394.             </div>
395.             <div class="result" id="quiz-result" aria-live="polite" aria-atomic="true">
