406.     const form = document.getElementById("quiz-form");
407.     const result = document.getElementById("quiz-result");
408. 
409.     function getSelections(questionId) {
410.       return [...form.querySelectorAll(`input[name="${questionId}"]:checked`)].map((input) => input.value);
411.     }
412. 
413.     function arraysEqual(a, b) {
414.       if (a.length !== b.length) return false;
415.       const left = [...a].sort();
416.       const right = [...b].sort();
417.       return left.every((value, index) => value === right[index]);
