   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --surface: rgba(255, 255, 255, 0.86);
       --surface-solid: #ffffff;
       --text: #162033;
       --muted: #5c6b84;
       --border: #d7dfec;
       --primary: #4f46e5;
       --primary-strong: #3730a3;
       --primary-soft: #eef2ff;
       --accent: #06b6d4;
       --shadow: 0 18px 48px rgba(17, 24, 39, 0.12);
       --radius: 24px;
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(79, 70, 229, 0.16), transparent 30%),
         radial-gradient(circle at top right, rgba(6, 182, 212, 0.16), transparent 25%),
         var(--bg);
     }

     a.skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       transform: translateY(-200%);
       padding: 0.75rem 1rem;
       background: var(--surface-solid);
       color: var(--text);
       border-radius: 999px;
       box-shadow: var(--shadow);
       z-index: 10;
     }

     a.skip-link:focus {
       transform: translateY(0);
     }

     main {
       width: min(960px, calc(100% - 2rem));
       margin: 0 auto;
       padding: 3rem 0 4rem;
     }

     .shell {
       display: grid;
       gap: 1.5rem;
     }

     .hero {
       padding: 2rem;
       border: 1px solid rgba(255, 255, 255, 0.7);
       border-radius: 32px;
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.88), rgba(255, 255, 255, 0.74));
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       margin: 0 0 0.75rem;
       padding: 0.35rem 0.7rem;
       border-radius: 999px;
       background: var(--primary-soft);
       color: var(--primary-strong);
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.5rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .hero p {
       max-width: 65ch;
       margin: 1rem 0 0;
       color: var(--muted);
       font-size: 1.05rem;
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .quiz-card {
       padding: 1.5rem;
       border-radius: 28px;
       border: 1px solid var(--border);
       background: var(--surface);
       box-shadow: var(--shadow);
       backdrop-filter: blur(10px);
     }

     .form-field {
       margin: 0;
     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-width: 0;
     }

     legend {
       width: 100%;
       margin-bottom: 0.65rem;
       padding: 0;
       color: var(--text);
       font-size: 1.08rem;
       font-weight: 700;
     }

     .help-text {
       margin: 0 0 1rem;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .options {
       display: grid;
       gap: 0.75rem;
     }

     .option {
       display: flex;
       align-items: flex-start;
       gap: 0.9rem;
       padding: 0.95rem 1rem;
       border: 1px solid var(--border);
       border-radius: 18px;
       background: rgba(255, 255, 255, 0.92);
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
       cursor: pointer;
     }

     .option:hover {
       border-color: rgba(79, 70, 229, 0.45);
       transform: translateY(-1px);
     }

     .option input {
       width: 1.15rem;
       height: 1.15rem;
       margin: 0.15rem 0 0;
       accent-color: var(--primary);
       flex: none;
     }

     .option-content {
       display: grid;
       gap: 0.2rem;
     }

     .option-title {
       font-weight: 650;
     }

     .option-desc {
       color: var(--muted);
       font-size: 0.95rem;
     }

     .option input:focus-visible {
       outline: 3px solid rgba(79, 70, 229, 0.35);
       outline-offset: 3px;
     }

     .option:has(input:focus-visible) {
       border-color: var(--primary);
       box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.12);
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
       align-items: center;
       justify-content: space-between;
       margin-top: 0.5rem;
       padding: 1rem 0 0;
       border-top: 1px solid rgba(215, 223, 236, 0.7);
     }

     .submit-btn {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.35rem;
       background: linear-gradient(135deg, var(--primary), #7c3aed);
       color: #fff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 14px 30px rgba(79, 70, 229, 0.24);
       transition: transform 0.2s ease, box-shadow 0.2s ease;
     }

     .submit-btn:hover {
       transform: translateY(-1px);
       box-shadow: 0 16px 34px rgba(79, 70, 229, 0.28);
     }

     .submit-btn:focus-visible {
       outline: 3px solid rgba(79, 70, 229, 0.3);
       outline-offset: 4px;
     }

     .hint {
       color: var(--muted);
       font-size: 0.94rem;
       margin: 0;
     }

     .result {
       min-height: 3rem;
       padding: 1rem 1.1rem;
       border-radius: 18px;
       background: rgba(239, 246, 255, 0.8);
       border: 1px solid rgba(79, 70, 229, 0.2);
       color: var(--text);
     }

     .score {
       margin: 0 0 0.25rem;
       font-size: 1.1rem;
       font-weight: 800;
     }

     .feedback {
       margin: 0;
       color: var(--muted);
     }

     @media (max-width: 640px) {
       main {
         width: min(100% - 1rem, 960px);
         padding: 2.25rem 0 3rem;
       }

       .hero,
       .quiz-card {
         padding: 1.25rem;
         border-radius: 22px;
       }

       .actions {
         align-items: stretch;
       }

       .submit-btn {
         width: 100%;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       html {
         scroll-behavior: auto;
       }

       *,
       *::before,
       *::after {
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
         transition-duration: 0.01ms !important;
         scroll-behavior: auto !important;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <main id="maincontent">
     <div class="shell" id="app"></div>
   </main>

   <script>
     const quizData = [
       {
         id: "languages",
         title: "Which of these are programming languages?",
         help: "Select all that apply.",
         options: [
           { id: "python", label: "Python", description: "General-purpose, high-level language." },
           { id: "javascript", label: "JavaScript", description: "Runs in browsers and on servers." },
           { id: "photoshop", label: "Photoshop", description: "A creative application, not a language." },
           { id: "rust", label: "Rust", description: "A systems language focused on safety." }
         ],
         correct: ["python", "javascript", "rust"]
       },
       {
         id: "paradigms",
         title: "Which languages are commonly used for web development?",
         options: [
           { id: "html", label: "HTML", description: "Markup for page structure." },
           { id: "css", label: "CSS", description: "Styles the look and layout." },
           { id: "lua", label: "Lua", description: "Used in games and embedded scripting." },
           { id: "typescript", label: "TypeScript", description: "Typed superset of JavaScript." }
         ],
         correct: ["html", "css", "typescript"]
       },
       {
         id: "typing",
         title: "Which languages are statically typed?",
         options: [
           { id: "java", label: "Java", description: "Statically typed and widely used." },
           { id: "csharp", label: "C#", description: "Statically typed with modern tooling." },
           { id: "perl", label: "Perl", description: "Traditionally dynamically typed." },
           { id: "go", label: "Go", description: "Statically typed and compiled." }
         ],
         correct: ["java", "csharp", "go"]
       }
     ];

     function createOption(questionId, option, index) {
       const id = `${questionId}-${option.id}`;
       return `
         <label class="option" for="${id}">
           <input type="checkbox" id="${id}" name="${questionId}" value="${option.id}">
           <span class="option-content">
             <span class="option-title">${option.label}</span>
             <span class="option-desc">${option.description}</span>
           </span>
         </label>
       `;
     }

     function createQuestion(question, index) {
       const helpId = `${question.id}-help`;
       const fieldsetDescribedBy = question.help ? ` aria-describedby="${helpId}"` : "";
       const helpMarkup = question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : "";

       return `
         <div class="form-field quiz-card">
           <fieldset id="${question.id}-fieldset"${fieldsetDescribedBy}>
             <legend>${index + 1}. ${question.title}</legend>
             ${helpMarkup}
             <div class="options">
               ${question.options.map((option, optionIndex) => createOption(question.id, option, optionIndex)).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function createQuizApp() {
       return `
         <section class="hero" aria-labelledby="quiz-title">
           <p class="eyebrow">Interactive quiz</p>
           <h1 id="quiz-title">Computer Languages Quiz</h1>
           <p>
             Test your knowledge of programming languages, web technologies, and typing styles.
             Each question allows multiple selections.
           </p>
         </section>

         <form id="quiz-form" novalidate>
           ${quizData.map(createQuestion).join("")}

           <div class="quiz-card">
             <div class="actions">
               <p class="hint">Choose one or more answers for each question, then check your score.</p>
               <button class="submit-btn" type="submit">Submit quiz</button>
             </div>
             <div class="result" id="quiz-result" aria-live="polite" aria-atomic="true">
               <p class="score">Ready when you are.</p>
               <p class="feedback">Your score will appear here after submission.</p>
             </div>
           </div>
         </form>
       `;
     }

     document.getElementById("app").innerHTML = createQuizApp();

     const form = document.getElementById("quiz-form");
     const result = document.getElementById("quiz-result");

     function getSelections(questionId) {
       return [...form.querySelectorAll(`input[name="${questionId}"]:checked`)].map((input) => input.value);
     }

     function arraysEqual(a, b) {
       if (a.length !== b.length) return false;
       const left = [...a].sort();
       const right = [...b].sort();
       return left.every((value, index) => value === right[index]);
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const unanswered = [];
       let score = 0;

       quizData.forEach((question) => {
         const selections = getSelections(question.id);
         if (selections.length === 0) {
           unanswered.push(question.id);
           return;
         }

         if (arraysEqual(selections, question.correct)) {
           score += 1;
         }
       });

       if (unanswered.length > 0) {
         const firstUnanswered = document.getElementById(`${unanswered[0]}-fieldset`);
         firstUnanswered?.scrollIntoView({ behavior: "smooth", block: "center" });
         const firstCheckbox = form.querySelector(`input[name="${unanswered[0]}"]`);
         firstCheckbox?.focus();
       }

       const answeredCount = quizData.length - unanswered.length;
       const scoreLine = `${score}/${quizData.length} correct`;
       const feedbackLine = unanswered.length
         ? `You answered ${answeredCount} of ${quizData.length} questions. Please complete the remaining question${unanswered.length === 1 ? "" : "s"}.`
         : score === quizData.length
           ? "Perfect score. Nice work."
           : score >= 2
             ? "Solid result. A couple of answers need a second look."
             : "Good start. Review the language categories and try again.";

       result.innerHTML = `
         <p class="score">${scoreLine}</p>
         <p class="feedback">${feedbackLine}</p>
       `;
     });
   </script>
 </body>
 </html>

')

